"""Disposable real HTTPS browser fixture. Never use with live Hub state or credentials."""
import asyncio
import base64
from datetime import datetime, timedelta, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import ipaddress
import json
import os
from pathlib import Path
import signal
import ssl
import threading
import time
from types import MappingProxyType, SimpleNamespace
from uuid import uuid4

from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.x509.oid import NameOID
from fastapi import FastAPI, Request
from starlette.responses import HTMLResponse, JSONResponse

from engineering_hub.auth import AuthConfig, SessionStore, require_human
from engineering_hub.repository import HubError, HubRepository
from engineering_hub.staging_api import attach_staging_routes
from engineering_hub.staging_preview import PreviewBroker
from engineering_hub.staging_resources import StagingResourceStore

ACTOR = 'human:1'
HUB = os.environ['TEST_HUB_ORIGIN']
PREVIEW = os.environ['TEST_PREVIEW_ORIGIN']
ROOT = Path('/tmp/preview-browser-fixture')
ROOT.mkdir(mode=0o700)
now = [time.time()]
repo = HubRepository(ROOT / 'hub.sqlite3')
sessions = SessionStore(ROOT / 'auth.sqlite3', clock=lambda: now[0])
config = AuthConfig(HUB, beau_github_id=1)
control = object()
resources = StagingResourceStore(repo, admin_actors=frozenset({ACTOR}),
    control_principal=control, clock=lambda: now[0])
resources.set_policy(ACTOR, 'engineering-hub', 0, {ACTOR: ['read', 'preview']})
broker = PreviewBroker(repo, resources, hub_origin=HUB, preview_origin=PREVIEW,
    session_alive=sessions.preview_session_alive, clock=lambda: now[0])
identities = []
for _ in range(2):
    job = resources.bind_job(control, str(uuid4()), project='engineering-hub',
        created_by='codex', source_commit='a'*40, artifact_digest='sha256:'+'b'*64)
    item = resources.register_resource(control, job['id'], 'preview')
    resources.mark_resource_ready(control, item['id'], item['revision'],
        preview_path='/staging/previews/synthetic/', size_bytes=2000)
    resources.update_job(control, job['id'], job['revision'], terminal=True)
    identities.append(item['id'])

# Original two-glyph font generated by generate_staging_preview_font.py, no copied font.
FONT = base64.b64decode('', validate=True)
FILES = MappingProxyType({
    'index.html': (b'<!doctype html><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="./style.css"><p id="out">loading</p><span id="font">A</span><script type="module" src="./app.js"></script>', 'text/html'),
    'style.css': (b'@font-face {font-family: OriginalHubFixture; src: url(./fixture.ttf) format("truetype");} #font {font-family: OriginalHubFixture;} #out { color: rgb(17, 34, 51); }', 'text/css'),
    'fixture.ttf': (FONT, 'font/ttf'),
    'app.js': (b"""import { label } from './lib.js';
const { suffix } = await import('./dynamic.js');
const data = await (await fetch('./data.json')).json();
const fonts = await document.fonts.load('16px OriginalHubFixture', 'A');
let parentReadable = false, cookieReadable = false;
try { void parent.document.title; parentReadable = true; } catch {}
try { void document.cookie; cookieReadable = true; } catch {}
document.querySelector('#out').textContent = label + suffix + ' ' + data.n;
window.fixtureFacts = { parentReadable, cookieReadable, opaque: self.origin === 'null',
    fontLoaded: fonts.length === 1 && fonts[0].status === 'loaded' && document.fonts.check('16px OriginalHubFixture', 'A') };
""", 'text/javascript'),
    'lib.js': (b"export const label = 'real';", 'text/javascript'),
    'dynamic.js': (b"export const suffix = '-gateway';", 'text/javascript'),
    'data.json': (b'{"n":42}', 'application/json'),
})
async def immutable_file(resource_id, path):
    if resource_id not in identities or path not in FILES or (resource_id == identities[1] and path != 'index.html'):
        raise HubError('not_found', 404)
    return FILES[path]

app = FastAPI()
@app.exception_handler(HubError)
async def hub_error(request, error):
    return JSONResponse({'code': error.code}, status_code=error.status)
def human(request, mutation=False):
    return require_human(request, config, sessions, mutation=mutation)
def binding(request):
    return sessions.preview_session_binding(human(request), request.cookies.get(config.cookie_name))
attach_staging_routes(app, SimpleNamespace(resources=resources), human, human,
    preview_broker=broker, preview_session=binding)

@app.post('/test/login')
async def login():
    session = sessions.create_session(1)
    response = JSONResponse({'csrf': session['csrf_token'], 'resources': identities})
    response.set_cookie(config.cookie_name, session['cookie_token'], secure=True, httponly=True, samesite='strict')
    return response

@app.post('/test/control/{action}')
async def mutate(action: str, request: Request):
    human(request, mutation=True)
    if action == 'logout':
        sessions.delete_session(request.cookies.get(config.cookie_name))
    elif action == 'revoke':
        policy = resources.get_policy(ACTOR, 'engineering-hub')
        resources.set_policy(ACTOR, 'engineering-hub', policy['revision'], {})
    elif action == 'restore':
        policy = resources.get_policy(ACTOR, 'engineering-hub')
        resources.set_policy(ACTOR, 'engineering-hub', policy['revision'], {ACTOR: ['read', 'preview']})
    elif action == 'expire':
        now[0] += 301
    else:
        return JSONResponse({}, status_code=404)
    return JSONResponse({'ok': True})

seen = {'files': set(), 'cookie': False, 'authorization': False, 'referer': False}
gateway = broker.app(immutable_file)
async def preview(scope, receive, send):
    headers = dict(scope['headers'])
    seen['cookie'] |= b'cookie' in headers
    seen['authorization'] |= b'authorization' in headers
    seen['referer'] |= b'referer' in headers
    name = scope['path'].rsplit('/', 1)[-1]
    if name in FILES:
        seen['files'].add(name)  # Only fixed fixture names; never capability paths.
    await gateway(scope, receive, send)

@app.get('/test/observations')
async def observations(request: Request):
    human(request)
    return {'files': sorted(seen['files']), **{key: seen[key] for key in ('cookie','authorization','referer')}}

@app.get('/')
async def page(request: Request):
    human(request)
    return HTMLResponse('<!doctype html><meta name="viewport" content="width=device-width"><title>Disposable Hub preview acceptance</title><main><h1>Preview acceptance</h1><iframe title="preview" sandbox="allow-scripts" referrerpolicy="no-referrer" style="width:100%;height:300px;border:0"></iframe></main>')

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass  # Never log URLs, cookies, capabilities or test credential values.
    def do_GET(self): self.dispatch()
    def do_POST(self): self.dispatch()
    def do_HEAD(self): self.dispatch()
    def dispatch(self):
        length = int(self.headers.get('content-length', 0))
        if not 0 <= length <= 65536:
            self.send_error(413); return
        body = self.rfile.read(length)
        headers = [(key.lower().encode(), value.encode()) for key, value in self.headers.items()]
        scope = {'type':'http', 'asgi':{'version':'3.0'}, 'http_version':'1.1',
            'method':self.command, 'scheme':'https', 'path':self.path.split('?',1)[0],
            'raw_path':self.path.split('?',1)[0].encode(), 'query_string':b'',
            'root_path':'', 'headers':headers, 'client':self.client_address, 'server':self.server.server_address}
        messages = []
        async def receive(): return {'type':'http.request', 'body':body, 'more_body':False}
        async def send(message): messages.append(message)
        asyncio.run((app if self.server.role == 'hub' else preview)(scope, receive, send))
        start = next(message for message in messages if message['type'] == 'http.response.start')
        self.send_response(start['status'])
        for key, value in start['headers']: self.send_header(key.decode(), value.decode())
        self.end_headers()
        if self.command != 'HEAD':
            for message in messages:
                if message['type'] == 'http.response.body': self.wfile.write(message.get('body', b''))

key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
name = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, 'disposable-preview-fixture')])
cert = (x509.CertificateBuilder().subject_name(name).issuer_name(name).public_key(key.public_key())
    .serial_number(x509.random_serial_number()).not_valid_before(datetime.now(timezone.utc)-timedelta(minutes=1))
    .not_valid_after(datetime.now(timezone.utc)+timedelta(hours=1))
    .add_extension(x509.SubjectAlternativeName([x509.DNSName('localhost'),x509.IPAddress(ipaddress.ip_address('127.0.0.1'))]),critical=False)
    .sign(key,hashes.SHA256()))
(ROOT/'key.pem').write_bytes(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
(ROOT/'cert.pem').write_bytes(cert.public_bytes(serialization.Encoding.PEM))
context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
context.load_cert_chain(ROOT/'cert.pem',ROOT/'key.pem')
servers=[]; threads=[]
for role, port in (('hub',8443),('preview',8444)):
    server=ThreadingHTTPServer(('0.0.0.0',port),Handler); server.role=role
    server.socket=context.wrap_socket(server.socket,server_side=True)
    thread=threading.Thread(target=server.serve_forever,daemon=True); thread.start()
    servers.append(server); threads.append(thread)
stopped=threading.Event()
signal.signal(signal.SIGTERM,lambda *_:stopped.set())
signal.signal(signal.SIGINT,lambda *_:stopped.set())
print('preview fixture ready',flush=True)
try: stopped.wait()
finally:
    for server in servers: server.shutdown(); server.server_close()
    for thread in threads: thread.join(timeout=2)
